const $=id=>document.getElementById(id);
function when(value){if(!value)return 'час не призначено';try{return new Intl.DateTimeFormat('uk-UA',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Kyiv'}).format(new Date(value));}catch{return 'некоректний час';}}
async function load(){const button=$('premiere-refresh'),status=$('premiere-admin-status'),list=$('premiere-contacts');if(!list)return;button.disabled=true;status.textContent='Оновлюємо дані…';try{const response=await fetch('/api/premiere/admin',{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw new Error();const data=await response.json();$('premiere-total').textContent=data.total||0;$('premiere-eligible').textContent=data.eligible||0;$('premiere-opened').textContent=data.opened||0;list.replaceChildren();for(const contact of (data.contacts||[]).slice(0,30)){const row=document.createElement('div');row.className='premiere-contact-row';const person=document.createElement('strong');person.textContent=contact.user_name||contact.username||contact.telegram_id;const states=[contact.eligible&&!contact.unsubscribed?'Допущено':'Без доступу',when(contact.webinar_at)];if(contact.reminder_sent_at)states.push('нагадування надіслано');if(contact.room_link_sent_at)states.push('посилання надіслано');if(contact.room_opened_at)states.push('відкрив кімнату');const meta=document.createElement('span');meta.textContent=states.join(' · ');row.append(person,meta);list.append(row);}status.textContent=data.premiereId?`Постійна прем’єра призначена · допущено ${data.eligible||0}`:'Спочатку призначте один запис постійною прем’єрою.';}catch{status.textContent='Не вдалося завантажити статуси прем’єри.';}finally{button.disabled=false;}}
$('premiere-refresh')?.addEventListener('click',load);window.addEventListener('recording:published',load);load();
